mapper.select:
SELECT
	COUNT(*)
FROM
	photo.photo_mst

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND photo_no = #{photoNo, typeHandler=com.web.gallery.type_handler.PhotoNoTypeHandler}
	 AND is_deleted = #{isDeleted, typeHandler=com.web.gallery.type_handler.IsDeletedTypeHandler}
	 AND photo_at = #{photoAt, typeHandler=com.web.gallery.type_handler.PhotoAtTypeHandler}
	 AND location_no = #{locationNo, typeHandler=com.web.gallery.type_handler.LocationNoTypeHandler}
	 AND image_file_path = #{imageFilePath, typeHandler=com.web.gallery.type_handler.ImageFilePathTypeHandler}
	 AND photo_japanese_title = #{photoJapaneseTitle, typeHandler=com.web.gallery.type_handler.PhotoJapaneseTitleTypeHandler}
	 AND photo_english_title = #{photoEnglishTitle, typeHandler=com.web.gallery.type_handler.PhotoEnglishTitleTypeHandler}
	 AND caption = #{caption, typeHandler=com.web.gallery.type_handler.CaptionTypeHandler}
	 AND direction_kbn = #{directionKbn}::photo.direction_enum
	 AND focal_length = #{focalLength, typeHandler=com.web.gallery.type_handler.FocalLengthTypeHandler}
	 AND f_value = #{fValue, typeHandler=com.web.gallery.type_handler.FValueTypeHandler}
	 AND shutter_speed = #{shutterSpeed, typeHandler=com.web.gallery.type_handler.ShutterSpeedTypeHandler}
	 AND iso = #{iso, typeHandler=com.web.gallery.type_handler.IsoTypeHandler}

mapper.update:
