mapper.delete:
DELETE FROM
	photo.photo_mst

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND photo_no = #{photoNo, typeHandler=com.web.gallery.type_handler.PhotoNoTypeHandler}
